def choose_move(observation):
    # Defensive defaults
    x = observation.get("me_x", 0)
    y = observation.get("me_y", 0)

    # Try to sense goals or resources if present
    target = observation.get("target", None)
    resources = observation.get("resources", [])
    enemies = observation.get("enemies", [])
    allies = observation.get("allies", [])
    owned = observation.get("owned", [])
    territory = observation.get("territory", [])
    mode = observation.get("mode", None)

    # Initialize default move
    dx, dy = 0, 0

    # Simple robust heuristic across modes
    # 1) resource_collection: move toward nearest resource if available
    if resources:
        # pick resource closest to us
        best = None
        best_d2 = None
        for r in resources:
            rx = r.get("x", 0)
            ry = r.get("y", 0)
            d2 = (rx - x) * (rx - x) + (ry - y) * (ry - y)
            if best_d2 is None or d2 < best_d2:
                best = (rx, ry)
                best_d2 = d2
        if best is not None:
            rx, ry = best
            dx = 0
            dy = 0
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            return [dx, dy]

    # 2) pursuit_evasion: move toward closest target if present, else away from threat
    if mode == "pursuit" or enemies:
        if enemies:
            # pursue the closest enemy if it looks capturable
            best_e = None
            best_de2 = None
            for e in enemies:
                ex = e.get("x", 0)
                ey = e.get("y", 0)
                d2 = (ex - x) * (ex - x) + (ey - y) * (ey - y)
                if best_de2 is None or d2 < best_de2:
                    best_e = (ex, ey)
                    best_de2 = d2
            if best_e is not None:
                ex, ey = best_e
                dx = 0
                dy = 0
                if ex > x:
                    dx = 1
                elif ex < x:
                    dx = -1
                if ey > y:
                    dy = 1
                elif ey < y:
                    dy = -1
                return [dx, dy]
        # default toward center if no enemies info
        if "center" in observation:
            cx, cy = observation.get("center", (0, 0))
            if cx > x:
                dx = 1
            elif cx < x:
                dx = -1
            if cy > y:
                dy = 1
            elif cy < y:
                dy = -1
            return [dx, dy]

    # 3) territory_control: move toward owned/no-man's land outskirts or toward target if provided
    if territory:
        # try to move toward a tile not owned if possible
        # pick a adjacent tile that is least likely owned
        best_dir = None
        for ax, ay, cand in [ (x+1,y, (1,0)), (x-1,y, (-1,0)), (x,y+1, (0,1)), (x,y-1, (0,-1)) ]:
            # cand free
            tile = observation.get("grid", None)
            owned_here = False
            if tile and isinstance(tile, list):
                # check boundary index
                pass
            # fall back: use whether candidate in territory list
            if territory:
                if (ax, ay) not in territory:
                    best_dir = cand
                    break
        if best_dir:
            dx, dy = best_dir
            return [dx, dy]

    # Fallback: move randomly within allowed neighborhood by deterministic rule
    # Prefer staying close to current position but make a move
    # Try to bias toward available resource or center if known
    if target is not None:
        tx = target.get("x", x)
        ty = target.get("y", y)
        if tx > x:
            return [1, 0]
        if tx < x:
            return [-1, 0]
        if ty > y:
            return [0, 1]
        if ty < y:
            return [0, -1]

    # Default small step toward origin (0,0) or stay
    if x != 0:
        dx = -1 if x > 0 else 1
        return [dx, 0]
    if y != 0:
        dy = -1 if y > 0 else 1
        return [0, dy]

    return [0, 0]

